cases.C001??={run:fresh1(),record:null};cases.C002??={run:fresh2(),record:null};cases.C003??={run:fresh3(),record:null};cases.C004??={run:fresh4(),record:null};cases.C001.run={...fresh1(),...cases.C001.run};cases.C002.run={...fresh2(),...cases.C002.run};cases.C003.run={...fresh3(),...cases.C003.run};cases.C004.run={...fresh4(),...cases.C004.run,sceneProgress:{...fresh4().sceneProgress,...cases.C004.run?.sceneProgress},statementChecks:{...cases.C004.run?.statementChecks}};
