caseShelf=()=>{const open2=unlocked2(),open3=unlocked3(),cards=[['C001','KES 001','Misteri Beg Merah','⭐ Jejak Awal',true,decorativeBag()],['C002','KES 002','Misteri Label Tertukar','⭐⭐ Jejak Tajam',open2,orderBagsArt],['C003','KES 003','Misteri Nota Terpotong','⭐⭐⭐ Jejak Cermat',open3,noteArt]];return `<aside class="case-shelf" aria-label="Senarai Fail Kes"><h2><svg class="icon" aria-hidden="true"><use href="#i-folder"/></svg>Fail Kes</h2><div class="case-list">${cards.map(([id,num,title,diff,open,art])=>`<button class="case-card ${activeCase===id?'active':open?'':'locked'}" data-case="${id}" ${open?'':'disabled'} aria-label="${open?num+', '+title:num+', terkunci'}">${open?art:'<svg class="icon" aria-hidden="true"><use href="#i-lock"/></svg>'}<span><strong>${num}</strong>${open?title:'???'}<small>${open?diff:'Terkunci'}</small></span></button>`).join('')}${[4,5].map(n=>`<button class="case-card locked" disabled aria-label="KES 00${n}, terkunci"><svg class="icon"><use href="#i-lock"/></svg><span><strong>KES 00${n}</strong>???<small>Terkunci</small></span></button>`).join('')}</div></aside>`};
homeView=()=>{const meta={C001:['KES 001','Misteri Beg Merah','⭐ Jejak Awal','Beg merah Aynaa hilang selepas rehat. Lima petunjuk menanti.',bagArt,'Bukti utama: beg merah','5–7'],C002:['KES 002','Misteri Label Tertukar','⭐⭐ Jejak Tajam','Dua beg pesanan mempunyai label nama yang mengelirukan.',orderBagsArt,'Bukti utama: dua beg berbeza','7–10'],C003:['KES 003','Misteri Nota Terpotong','⭐⭐⭐ Jejak Cermat','Empat cebisan perlu disusun untuk memahami satu arahan.',noteArt,'Bukti utama: empat cebisan nota','8–12']}[activeCase],start=state.scene>0&&state.status!=='completed'?'Sambung siasatan →':state.status==='completed'?'Lihat keputusan →':activeCase==='C001'?'Buka surat pertama →':`Buka Fail ${meta[0]} →`;return `<main><div class="welcome-line">SELAMAT DATANG KE BAYURAYA · FAIL KES</div><div class="landing-layout"><section class="case-hero"><span class="file-tab">${meta[0]}</span><h1>${meta[1]}</h1><div class="case-overview"><div><span class="difficulty">${meta[2]}</span><p>${meta[3]}</p></div><figure class="evidence-photo">${meta[4]}<figcaption>${meta[5]}</figcaption></figure></div>${button(start,'start','primary')}<p class="meta">${meta[6]} minit · Tiada had masa · Kemajuan disimpan</p>${record?`<p class="meta">★ Rekod terbaik: ${record.stars} bintang · ${record.xpEarned} XP</p>`:''}</section><aside class="klu">${companionArt(state.status==='completed'?'celebrate':'neutral')}<div class="klu-message"><div class="eyebrow">KLU · RAKAN DETEKTIF</div><p>${activeCase==='C003'?'Kita perlu mencari, memahami dan menyusun empat cebisan nota.':'Kamu detektif utama. Saya bantu mencari petunjuk.'}</p></div></aside>${caseShelf()}</div><div class="learning-strip"><span><b>01</b> Cari petunjuk</span><span><b>02</b> Baca dengan cermat</span><span><b>03</b> Sambungkan bukti</span></div></main>`};
const tasks1={2:{q:'Cari benda yang disebut dalam ayat Aynaa.',h:['Cari nama benda dalam ayat.','Perhatikan kawasan objek yang mula bercahaya.','Pilih beg merah dahulu, kemudian kerusi.']},4:{q:'Siapakah orang yang sedang bercakap?',opts:['Beg','Kerusi','Aynaa','Sekolah'],answer:'Aynaa',name:'Aynaa',quote:'Pagi tadi saya membawa beg merah ke sekolah.<br>Sebelum rehat, saya meletakkannya di sebelah kerusi saya.<br>Selepas rehat, beg itu sudah tiada.',h:['Cari nama seseorang.','Nama itu tertera di atas kenyataan saksi.','Pilih “Aynaa”.'],learn:'KATA NAMA KHAS',explain:'Nama khas ialah nama tertentu seperti Aynaa, Bayuraya atau Sekolah Bayuraya.',clue:2},5:{q:'Pilih perkataan yang menunjukkan tindakan.',opts:['Dia','membawa','sebuah','beg','merah'],answer:'membawa',name:'Hakim',quote:'Selepas rehat, saya kembali ke kelas.<br>Saya nampak Cikgu Farah berdiri dekat pintu.<br>Dia membawa sebuah beg merah.',h:['Cari perkataan yang menunjukkan perbuatan.','Apakah yang dilakukan oleh Cikgu Farah?','Pilih “membawa”.'],learn:'KATA KERJA',explain:'Kata kerja menunjukkan perbuatan atau tindakan.',clue:3},6:{q:'Di manakah Mei Ling melihat beg itu?',opts:['kelas','kantin','perpustakaan','taman'],answer:'perpustakaan',name:'Mei Ling',quote:'Saya pergi ke perpustakaan selepas rehat.<br>Saya nampak sebuah beg merah di atas meja pustakawan.',h:['Cari nama tempat dalam kenyataan.','Baca ayat pertama Mei Ling.','Pilih “perpustakaan”.'],clue:4},8:{q:'Cikgu Farah ______ beg yang tertinggal kepada pustakawan.',opts:['membaca','menyerahkan','duduk','melukis'],answer:'menyerahkan',name:'Pustakawan',quote:'Cikgu Farah datang ke sini selepas rehat.<br>Dia menemui sebuah beg yang tertinggal di dalam kelas.<br>Cikgu Farah menyerahkan beg itu kepada saya supaya selamat.',h:['Cari tindakan yang berlaku kepada beg.','Baca: “Cikgu Farah menyerahkan beg itu kepada saya.”','Pilih “menyerahkan”.'],clue:5},9:{h:['Baca semula kad petunjuk di bawah.','Aynaa ialah pemilik. Cikgu Farah membawa beg.','Pilih: memiliki, membawa, dibawa ke.']},10:{h:['Padankan teori dengan semua lima petunjuk.','Mei Ling hanya melihat beg. Pustakawan menyimpannya supaya selamat.','Pilih teori B: Aynaa tertinggal beg dan Cikgu Farah menyelamatkannya.']}};
const tasks2={2:{q:'Perkataan manakah menerangkan saiz beg Ammar?',opts:['biru','kecil','beg','roket'],answer:'kecil',name:'Ammar',portrait:'assets/ammar.svg',quote:'Pesanan saya berada di dalam <b>beg biru kecil dengan pelekat roket</b>. Label namanya sepatutnya AMMAR.',h:['Cari perkataan yang menerangkan saiz.','Bandingkan “biru” dengan “kecil”.','Pilih “kecil”.'],learn:'KATA ADJEKTIF',explain:'“Kecil” menerangkan saiz beg. Perkataan seperti ini ialah kata adjektif.'},3:{q:'Apakah warna beg yang diterangkan oleh Sofia?',opts:['putih','biru','merah jambu','besar'],answer:'merah jambu',name:'Sofia',portrait:'assets/sofia.svg',quote:'Pesanan saya berada di dalam <b>beg merah jambu besar dengan reben putih</b>. Label namanya sepatutnya SOFIA.',h:['Cari perkataan yang menerangkan warna beg.','“Putih” menerangkan reben, bukan beg.','Pilih “merah jambu”.'],learn:'KATA ADJEKTIF',explain:'“Merah jambu” menerangkan warna beg.',clue:2},6:{q:'Label-label itu dipasang semula tanpa ______ penerangan beg.',opts:['membaca','memeriksa','mengira','membeli'],answer:'memeriksa',name:'Pekerja Kedai Matematik',portrait:'assets/shop-worker.svg',quote:'Dua label nama terjatuh berhampiran rak pengambilan. Saya memasangnya semula tanpa memeriksa penerangan pada setiap beg.',h:['Cari tindakan yang patut dibuat sebelum label dipasang.','Pekerja perlu membandingkan label dengan penerangan beg.','Pilih “memeriksa”.'],learn:'PEMAHAMAN AYAT',explain:'Memeriksa penerangan beg dapat memastikan label dipasang dengan betul.',clue:5},7:{h:['Baca semula empat hubungan.','Bezakan pemilik beg dengan nama pada label.','Pilih: memiliki, memiliki, berlabel, berlabel.']},8:{h:['Beg sepadan dengan penerangan pelanggan, tetapi label namanya tidak sepadan.','Kedua-dua label terjatuh dan dipasang semula.','Pilih teori B: beg tidak tertukar, label dipasang pada beg yang salah.']}};
const tasks3={3:{q:'Apakah lokasi yang disebut?',opts:['di atas meja','di belakang rak biru','di kaunter','di dalam kotak'],answer:'di belakang rak biru',name:'Ivy Chian',portrait:'assets/ivy.svg',quote:'Saya menjumpai cebisan ini berhampiran meja membaca: <b>“di belakang rak biru”</b>.',h:['Cari frasa yang menunjukkan tempat.','Cebisan itu menyebut rak dan warnanya.','Pilih “di belakang rak biru”.'],learn:'KEDUDUKAN',explain:'“Di belakang” menunjukkan kedudukan sesuatu.',clue:3},4:{q:'Bilakah arahan itu perlu dilakukan?',opts:['sebelum sekolah','selepas waktu rehat','pada waktu malam','esok'],answer:'selepas waktu rehat',name:'Kumar',portrait:'assets/kumar.svg',quote:'Saya menjumpai cebisan terakhir dekat troli buku: <b>“selepas waktu rehat.”</b>',h:['Cari frasa yang menunjukkan masa.','Baca cebisan selepas perkataan “selepas”.','Pilih “selepas waktu rehat”.'],learn:'MASA',explain:'Frasa itu memberitahu bila arahan perlu dilakukan.',clue:4},5:{h:['Arahan biasanya bermula dengan perbuatan.','Cari cebisan yang bermula dengan “Letakkan”.','Pilih cebisan seterusnya mengikut urutan ayat.']},6:{q:'Bahagian manakah membantu kita mengetahui lokasi?',opts:['letakkan','kotak','di belakang','selepas'],answer:'di belakang',name:'Arahan lengkap',quote:'“'+fragments.join(' ')+'”',h:['Cari bahagian yang menunjukkan kedudukan.','Kedudukan sasaran dibandingkan dengan rak biru.','Pilih “di belakang”.'],learn:'KEDUDUKAN',explain:'“Di belakang” membantu kita mengetahui kedudukan tempat.'},8:{q:'Adakah semua cebisan ini berasal daripada nota yang sama?',opts:['Ya, satu arahan','Tidak, empat arahan','Hanya dua cebisan','Tidak pasti'],answer:'Ya, satu arahan',name:'Pustakawan Bayuraya',portrait:'assets/shop-worker.svg',quote:'Keempat-empat cebisan ini berasal daripada satu nota arahan: <b>“'+fragments.join(' ')+'”</b>',h:['Pustakawan mengenali nota asal.','Semua cebisan bersambung menjadi satu ayat.','Pilih “Ya, satu arahan”.'],clue:5},9:{h:['Ikut urutan ayat lengkap.','A diikuti B, B diikuti C, C diikuti D.','Hubungkan arahan lengkap dengan lokasinya.']},10:{h:['Baca ayat lengkap yang telah disusun.','Semua cebisan ialah satu arahan penempatan.','Pilih teori B: kotak diletakkan di atas meja kecil di belakang rak biru selepas rehat.']}};
tasks3[1]={q:'Apakah benda yang disebut?',opts:['rak biru','kotak kad cerita','meja membaca','troli buku'],answer:'kotak kad cerita',h:['Cari nama barang dalam cebisan A.','Baca perkataan selepas “Letakkan”.','Pilih “kotak kad cerita”.'],clue:1};
let tasks4={};
const task=()=>activeCase==='C001'?tasks1[state.scene]:activeCase==='C002'?tasks2[state.scene]:activeCase==='C003'?tasks3[state.scene]:tasks4[state.scene];
function activeSceneTask(){if(activeCase==='C002'){if(state.scene===1&&!state.solved[1])return{sceneId:'mathShop',target:'resit ammar',h:['Cari kertas maklumat pesanan berhampiran rak pengambilan.','Perhatikan kertas kecil yang mula bercahaya.','Pilih “Resit pesanan Ammar”.']};if(state.scene===4&&!state.solved[4])return{sceneId:'mathShop',target:'beg biru ammar',h:['Cari beg yang warnanya disebut oleh Ammar.','Perhatikan beg kecil yang mula bercahaya.','Pilih beg biru kecil dengan pelekat roket.']};if(state.scene===5&&!state.solved[5])return{sceneId:'mathShop',target:'beg merah jambu sofia',h:['Cari beg besar yang diterangkan oleh Sofia.','Perhatikan beg bereben yang mula bercahaya.','Pilih beg merah jambu besar dengan reben putih.']};return}if(state.scene===2&&!state.solved[2])return{sceneId:'classroom',target:state.objects.length?'kerusi':'beg',h:task().h};if(state.scene===8&&!state.libraryEntered&&!state.solved[8]){const found=sceneDone('library');return found.includes('beg perpustakaan')?{sceneId:'library',target:'pustakawan',h:['Pustakawan biasanya berada berhampiran kaunter.','Perhatikan kawasan kaunter yang mula bercahaya.','Pilih pustakawan di belakang kaunter.']}:{sceneId:'library',target:'beg perpustakaan',h:['Mei Ling kata beg itu berada berhampiran tempat pustakawan.','Perhatikan kawasan kaunter yang mula bercahaya.','Pilih beg merah yang disimpan di tepi kaunter.']}}}
const priorActiveSceneTask=activeSceneTask;
activeSceneTask=function(){if(activeCase==='C003'){if(state.scene===1&&!state.solved[1])return{sceneId:'readingCorner',target:'cebisan a',h:['Cari cebisan yang menyebut barang.','Perhatikan cebisan berhampiran kotak kad cerita.','Pilih cebisan A: “Letakkan kotak kad cerita”.']};if(state.scene===2&&!state.solved[2])return{sceneId:'readingCorner',target:'cebisan b',h:['Cari cebisan yang menunjukkan kedudukan di atas sesuatu.','Perhatikan cebisan berhampiran meja membaca.','Pilih cebisan B: “di atas meja kecil”.']};if(state.scene===7&&!state.solved[7])return{sceneId:'readingCorner',target:'meja kecil',h:['Cari meja yang saiznya disebut dalam arahan.','Cari meja kecil berhampiran belakang rak biru.','Pilih meja kecil di belakang rak biru.']};return}return priorActiveSceneTask()};
function currentHelp(){return activeSceneTask()||task()}
function helpKey(){const active=activeSceneTask();return active?.sceneId&&active.sceneId!=='classroom'?`${state.scene}:${active.target}`:state.scene}
function helpLevel(){return state.hintLevels[helpKey()]||0}
function hint(){const t=currentHelp();if(!t)return;const key=helpKey();let l=state.hintLevels[key]||0;if(l<3){state.hintLevels[key]=++l;state.hintsUsed++}feedback=`Bantuan ${l}/3: ${t.h[l-1]}`;wrong=false;sound('hint');persist();render()}
function fail(msg){state.errors[state.scene]=(state.errors[state.scene]||0)+1;feedback=msg;wrong=true;sound('wrong-soft');if(state.errors[state.scene]>=2&&currentHelp()){hint();wrong=true;feedback=msg+' '+feedback}persist();render()}
function solve(n){state.solved[state.scene]=true;if(n)state.cluesFound=Math.max(state.cluesFound,n);feedback='✓ Bagus, bukti ini sepadan!';wrong=false;sound(n?'clue-found':'correct');persist();render()}
function go(n){state.scene=n;feedback='';wrong=false;persist();render();window.scrollTo(0,0)}
function witness2(t,done){const case3=activeCase==='C003',role=case3?(t.name==='Pustakawan Bayuraya'?'Pustakawan':'Penduduk Bayuraya'):(t.name==='Ammar'||t.name==='Sofia'?'Pelanggan Kedai Matematik':'Pekerja kedai');return `<div class="eyebrow">${case3?'PERPUSTAKAAN BAYURAYA · SUDUT BACAAN':'KEDAI MATEMATIK · SAKSI'}</div><div class="aynaa-card"><img src="${t.portrait}" alt="Potret ${t.name}" width="62" height="72"><span><b>${t.name}</b>${role}</span></div><div class="quote">${t.quote}</div><h3>${t.q}</h3><div class="choices">${t.opts.map(o=>`<button data-answer="${o}" ${done?'disabled':''} class="${done&&o===t.answer?'selected':''} ${helpLevel()>=3&&o===t.answer?'hinted':''}">${o}</button>`).join('')}</div>${done?`${t.learn?`<div class="feedback"><b>📖 ${t.learn}</b><br>${t.explain}</div>`:''}${t.clue?`<div class="evidence"><small>PETUNJUK ${t.clue} DITEMUI</small>${clues[t.clue-1]}</div>`:''}${button('Teruskan →','next','primary')}`:''}`}
function renderCase2(){let body='',s=state.scene,t=task(),help=currentHelp(),done=state.solved[s],progress=sceneDone('mathShop');
 if(file)body=`<h2>Fail Kes · Misteri Label Tertukar</h2>${clues.slice(0,state.cluesFound).map((c,i)=>`<div class="evidence"><small>PETUNJUK ${i+1}</small>${c}</div>`).join('')}${state.cluesFound===0?'<p>Belum ada petunjuk. Mari ke Kedai Matematik.</p>':''}${button('Kembali','closefile','primary')}`;
 else if(s===0)body=`<div class="eyebrow">KES 002 · KEDAI MATEMATIK</div><h2>Misteri Label Tertukar</h2><div class="letter"><p>Ada kekeliruan di Kedai Matematik. Ammar dan Sofia menerima beg dengan nama yang pelik.</p><p>Kita perlu membandingkan penerangan beg dengan label namanya.</p></div>${button('Pergi ke Kedai Matematik →','next','primary')}`;
 else if(s===1)body=`<div class="eyebrow">KEDAI MATEMATIK · SIASATAN</div><div class="scene-heading"><div><span class="scene-memory">MAKLUMAT PESANAN</span><h2>Cari maklumat pesanan Ammar.</h2></div><span class="scene-step">1/3 carian</span></div><p class="scene-instruction">Cari <b>resit pesanan Ammar</b>.</p>${renderScene(scenes.mathShop,help?.target,done,progress)}${done?`<div class="evidence"><small>PETUNJUK 1 DITEMUI</small>${clues[0]}</div>${button('Tanya Ammar →','next','primary')}`:''}`;
 else if(s===2||s===3||s===6)body=witness2(t,done);
 else if(s===4)body=`<div class="eyebrow">KEDAI MATEMATIK · PADANKAN PENERANGAN</div><div class="scene-heading"><div><span class="scene-memory">PESANAN AMMAR</span><h2>Cari beg Ammar.</h2></div><span class="scene-step">2/3 carian</span></div><div class="quote">“Beg biru kecil dengan pelekat roket.”</div><p class="scene-instruction">Cari beg yang sepadan dengan penerangan Ammar.</p>${renderScene(scenes.mathShop,help?.target,done,progress)}${done?`<div class="evidence"><small>PETUNJUK 3 DITEMUI</small>${clues[2]}</div>${button('Cari beg Sofia →','next','primary')}`:''}`;
 else if(s===5)body=`<div class="eyebrow">KEDAI MATEMATIK · PADANKAN PENERANGAN</div><div class="scene-heading"><div><span class="scene-memory">PESANAN SOFIA</span><h2>Cari beg Sofia.</h2></div><span class="scene-step">3/3 carian</span></div><div class="quote">“Beg merah jambu besar dengan reben putih.”</div><p class="scene-instruction">Cari beg yang sepadan dengan penerangan Sofia.</p>${renderScene(scenes.mathShop,help?.target,done,progress)}${done?`<div class="evidence"><small>PETUNJUK 4 DITEMUI</small>${clues[3]}</div>${button('Tanya pekerja kedai →','next','primary')}`:''}`;
 else if(s===7)body=`<div class="eyebrow">PETUNJUK 5/5 · PAPAN BUKTI</div><h2>Bezakan beg dengan label namanya.</h2><p>Lengkapkan empat hubungan berdasarkan penerangan dan label.</p><div class="connections">${[['AMMAR','BEG BIRU KECIL',['melihat','memiliki','berlabel']],['SOFIA','BEG MERAH JAMBU BESAR',['memiliki','membawa','berlabel']],['BEG BIRU KECIL','SOFIA',['memiliki','berlabel','membawa']],['BEG MERAH JAMBU BESAR','AMMAR',['memiliki','berlabel','membaca']]].map(([a,b,opts],i)=>`<div class="connection"><b>${a}</b><span>→</span><select aria-label="Hubungan ${a} kepada ${b}" data-link="${i}" ${done?'disabled':''}><option value="">Pilih hubungan…</option>${opts.map(o=>`<option ${state.links[i]===o?'selected':''}>${o}</option>`).join('')}</select><span>→</span><b>${b}</b></div>`).join('')}</div><div class="actions">${button(done?'Buat deduksi →':'Semak sambungan',done?'next':'check2','primary')}</div>${done?'<div class="feedback">✧ BUKTI SEPADAN. Beg betul, tetapi label namanya bersilang!</div>':''}`;
 else if(s===8)body=`<div class="eyebrow">DEDUKSI AKHIR</div><h2>Apa sebenarnya yang berlaku?</h2><p>Gunakan penerangan beg, label nama dan kenyataan pekerja.</p><div class="choices vertical">${['A · Ammar tersilap mengambil beg Sofia dengan sengaja.','B · Beg Ammar dan Sofia tidak tertukar. Label nama dipasang pada beg yang salah.','C · Kedai menyediakan dua pesanan baharu yang salah.'].map((o,i)=>`<button data-theory2="${i}">${o}</button>`).join('')}</div>${state.errors[s]?'<div class="evidence">Ammar → beg biru kecil → label SOFIA<br>Sofia → beg merah jambu besar → label AMMAR</div>':''}`;
 else if(s===9)body=`<div class="celebrate"><div class="eyebrow">✧ KES SELESAI!</div><h2>Misteri Label Tertukar</h2>${orderBagsArt}<div class="quote"><b>Pekerja kedai:</b> Begnya betul. Saya tersilap memasang semula label nama yang terjatuh.</div><p>Tiada beg yang tertukar. Ammar dan Sofia menerima pesanan mereka selepas label dibetulkan.</p>${button('Lihat keputusan →','next','primary')}</div>`;
 else body=`<div class="celebrate"><div class="tag">KES 002 SELESAI</div><h2>Tahniah, Detektif!</h2><div class="stars" aria-label="${state.stars} daripada 3 bintang">${'★'.repeat(state.stars)}${'☆'.repeat(3-state.stars)}</div><p>Kamu berjaya merungkai Misteri Label Tertukar.</p><div class="stats"><div><b>5/5</b><span>Petunjuk ditemui</span></div><div><b>+${state.xpEarned}</b><span>XP diperoleh</span></div><div><b>${state.hintsUsed}</b><span>Bantuan digunakan</span></div></div><div class="skills"><span>🎨 Warna</span><span>📏 Saiz</span><span>🏷 Kata adjektif</span><span>✧ Pemahaman ayat</span></div><div class="actions">${button('Lihat Fail Kes','file','primary')}${button('Kembali ke agensi','home')}${button('Main semula','replay')}</div><p class="meta">Rekod kedua-dua kes kekal disimpan.</p></div>`;
 app.innerHTML=`<main><div class="topline">${button('← Agensi','home')}<span class="tag">KES 002 · ${state.cluesFound}/5 PETUNJUK</span>${button('▤ Fail Kes','file')}</div><div class="layout"><section class="panel">${body}${feedback?`<div role="status" class="feedback ${wrong?'wrong':''}">${feedback}</div>`:''}</section><aside class="klu">${companionArt(kluMode(s,done))}<div class="klu-message"><div class="eyebrow">KLU · RAKAN DETEKTIF</div><p>${s>=9?'Penerangan beg membantu kita membezakan benda daripada label namanya.':s===7?'Susun siapa memiliki beg dan nama yang tertera pada label.':'Bandingkan warna, saiz, tanda khas dan label nama dengan teliti.'}</p>${help&&!done&&!file?button('☀ Bantuan '+helpLevel()+'/3','hint'):''}<p class="meta">Kemajuan disimpan secara automatik.</p></div></aside>${caseShelf()}</div></main>`}
