function renderSequenceTask(){const order=[2,0,3,1],next=state.sequence.length,level=helpLevel();return `<div class="sequence-progress" aria-label="Urutan cebisan dipilih">${[0,1,2,3].map(i=>`<span class="sequence-slot ${i<next?'filled':''}"><strong>${i+1}</strong><span>${state.sequence[i]!==undefined?fragments[state.sequence[i]]:'Pilih cebisan'}</span></span>`).join('')}</div><div class="sequence-cards" aria-label="Cebisan nota yang tersedia">${order.map(i=>`<button data-fragment="${i}" ${state.sequence.includes(i)||state.solved[5]?'disabled':''} class="sequence-card ${state.sequence.includes(i)?'chosen':''} ${level>=2&&i===next?'hint-next':''}" aria-label="Cebisan ${'ABCD'[i]}: ${fragments[i]}"><b>CEBISAN ${'ABCD'[i]}</b><span>${fragments[i]}</span></button>`).join('')}</div>${button('Tetapkan semula urutan','reset-sequence')}`}
function renderCase3(){let body='',s=state.scene,t=task(),help=currentHelp(),done=state.solved[s],progress=sceneDone('readingCorner');if(file)body=`<h2>Fail Kes · Misteri Nota Terpotong</h2>${clues.slice(0,state.cluesFound).map((c,i)=>`<div class="evidence"><small>PETUNJUK ${i+1}</small>${c}</div>`).join('')}${button('Kembali','closefile','primary')}`;else if(s===0)body=`<div class="eyebrow">KES 003 · SUDUT BACAAN</div><h2>Misteri Nota Terpotong</h2><div class="letter"><p>Kotak Kad Cerita Bayuraya sudah tiba. Arahan penempatannya terkoyak menjadi empat cebisan.</p></div>${button('Pergi ke Sudut Bacaan →','next','primary')}`;else if(s===1||s===2){const id=s===1?'A':'B';body=`<div class="eyebrow">PERPUSTAKAAN BAYURAYA · SUDUT BACAAN</div><h2>Cari Cebisan ${id}.</h2><p>${s===1?'Cari cebisan yang menyebut barang yang perlu diletakkan.':'Cari cebisan yang menunjukkan kedudukan di atas sesuatu.'}</p>${renderScene(scenes.readingCorner,help?.target,done,progress)}${s===1&&progress.includes('cebisan a')&&!done?`<div class="quote">“${fragments[0]}”</div><h3>${t.q}</h3><div class="choices">${t.opts.map(o=>`<button data-answer="${o}">${o}</button>`).join('')}</div>`:''}${done?`<div class="evidence"><small>PETUNJUK ${s} DITEMUI</small>${clues[s-1]}</div>${button(s===1?'Cari Cebisan B →':'Tanya Ivy →','next','primary')}`:''}`;}else if(s===3||s===4||s===8)body=witness2(t,done);else if(s===5)body=`<div class="eyebrow">SUSUN CEBISAN</div><h2>Bina arahan lengkap.</h2><p>Pilih cebisan satu demi satu mengikut urutan ayat.</p>${renderSequenceTask()}${done?`<div class="quote">“${fragments.join(' ')}”</div>${button('Fahami lokasi →','next','primary')}`:''}`;else if(s===6)body=witness2(t,done);else if(s===7)body=`<div class="eyebrow">GUNAKAN BAHASA UNTUK BERTINDAK</div><h2>Cari meja kecil di belakang rak biru.</h2><div class="quote">“${fragments.join(' ')}”</div>${renderScene(scenes.readingCorner,help?.target,done,progress)}${done?button('Tanya pustakawan →','next','primary'):''}`;else if(s===9)body=`<div class="eyebrow">PETUNJUK 5/5 · PAPAN BUKTI</div><h2>Sambungkan urutan arahan.</h2><div class="connections">${[['CEBISAN A','CEBISAN B'],['CEBISAN B','CEBISAN C'],['CEBISAN C','CEBISAN D'],['ARAHAN LENGKAP','MEJA KECIL DI BELAKANG RAK BIRU']].map(([a,b],i)=>`<div class="connection"><b>${a}</b><select data-link="${i}" aria-label="Hubungan ${a} kepada ${b}" ${done?'disabled':''}><option value="">Pilih hubungan…</option>${(i<3?['diikuti oleh','berasingan']:['lokasi','masa']).map(o=>`<option ${state.links[i]===o?'selected':''}>${o}</option>`).join('')}</select><b>${b}</b></div>`).join('')}</div>${button(done?'Buat deduksi →':'Semak sambungan',done?'next':'check3','primary')}`;else if(s===10)body=`<div class="eyebrow">DEDUKSI AKHIR</div><h2>Apakah sebenarnya maksud semua cebisan nota?</h2><div class="choices vertical">${['A · Cebisan itu ialah empat arahan yang berbeza.','B · Cebisan itu membentuk satu arahan: kotak kad cerita perlu diletakkan di atas meja kecil di belakang rak biru selepas waktu rehat.','C · Kotak itu perlu dikembalikan ke kaunter perpustakaan.'].map((o,i)=>`<button data-theory3="${i}">${o}</button>`).join('')}</div>`;else if(s===11)body=`<div class="celebrate"><div class="eyebrow">✧ KES SELESAI!</div><h2>Misteri Nota Terpotong</h2>${noteArt}<p>Empat cebisan membentuk satu arahan lengkap.</p>${button('Lihat keputusan →','next','primary')}</div>`;else body=`<div class="celebrate"><div class="tag">KES 003 SELESAI</div><h2>Tahniah, Detektif!</h2><div class="stars">${'★'.repeat(state.stars)}${'☆'.repeat(3-state.stars)}</div><div class="stats"><div><b>5/5</b><span>Petunjuk ditemui</span></div><div><b>+${state.xpEarned}</b><span>XP diperoleh</span></div></div><div class="actions">${button('Lihat Fail Kes','file','primary')}${button('Kembali ke agensi','home')}${button('Main semula','replay')}</div></div>`;app.innerHTML=`<main><div class="topline">${button('← Agensi','home')}<span class="tag">KES 003 · ${state.cluesFound}/5 PETUNJUK</span>${button('▤ Fail Kes','file')}</div><div class="layout"><section class="panel">${body}${feedback?`<div role="status" class="feedback ${wrong?'wrong':''}">${feedback}</div>`:''}</section><aside class="klu">${companionArt(kluMode(s,done))}<div class="klu-message"><div class="eyebrow">KLU · RAKAN DETEKTIF</div><p>${s===5?'Pilih cebisan mengikut aliran satu ayat lengkap.':'Baca setiap cebisan dengan cermat.'}</p>${(help||t)&&!done&&!file?button('☀ Bantuan '+helpLevel()+'/3','hint'):''}</div></aside>${caseShelf()}</div></main>`}
function handleCase3Click(b){if(b.dataset.object){const active=activeSceneTask();if(!active)return;state.attempts++;if(b.dataset.object!==active.target){fail('Bukan objek yang diminta. Baca arahan KLU dan cuba lagi.');return}state.sceneProgress.readingCorner??=[];if(!state.sceneProgress.readingCorner.includes(active.target))state.sceneProgress.readingCorner.push(active.target);if(state.scene===2){state.solved[2]=true;state.cluesFound=Math.max(state.cluesFound,2)}else if(state.scene===7)state.solved[7]=true;feedback='✓ Pilihan itu sepadan dengan arahan.';wrong=false;persist();render();return}if(b.dataset.fragment!==undefined){const i=Number(b.dataset.fragment),expected=state.sequence.length;state.attempts++;if(i!==expected){fail('Urutan itu belum tepat. Cari cebisan yang menyambung ayat.');return}state.sequence.push(i);feedback='✓ Cebisan seterusnya betul.';wrong=false;if(state.sequence.length===4)state.solved[5]=true;persist();render();return}if(b.dataset.answer){state.attempts++;b.dataset.answer===task().answer?solve(task().clue):fail('Belum tepat. Baca cebisan atau kenyataan sekali lagi.');return}if(b.dataset.theory3!==undefined){state.attempts++;if(b.dataset.theory3==='1'&&state.cluesFound===5&&state.solved[9]){state.status='completed';state.stars=state.hintsUsed<=2?3:state.hintsUsed<=5?2:1;state.xpEarned=160+(state.hintsUsed===0?30:0);state.completedAt=new Date().toISOString();if(!record||state.xpEarned>record.xpEarned)record={...state};go(11);sound('case-complete')}else fail('Teori itu belum sepadan. Semak urutan cebisan.');return}switch(b.dataset.action){case'start':home=false;file=false;render();break;case'home':home=true;file=false;persist();render();break;case'file':file=true;render();break;case'closefile':file=false;render();break;case'next':if([1,2,3,4,5,6,7,8,9].includes(state.scene)&&!state.solved[state.scene])return;go(state.scene+1);break;case'hint':hint();break;case'reset-sequence':state.sequence=[];state.solved[5]=false;feedback='Urutan ditetapkan semula.';persist();render();break;case'check3':state.attempts++;if(state.cluesFound===5&&state.links.join('|')==='diikuti oleh|diikuti oleh|diikuti oleh|lokasi'){solve();sound('board-complete')}else fail('Sambungan belum tepat. Ikut urutan ayat lengkap.');break;case'replay':state=fresh3();record=cases.C003.record||record;home=false;file=false;feedback='';persist();render();break}}
const hintBeforeC3=hint;hint=function(){if(activeCase!=='C003'||state.scene!==5){hintBeforeC3();return}const key=helpKey();let level=state.hintLevels[key]||0;if(level<3){state.hintLevels[key]=++level;state.hintsUsed++}const messages=['Arahan biasanya bermula dengan perbuatan.','Perhatikan cebisan yang perlu dipilih seterusnya.','Cebisan seterusnya ialah: “'+fragments[state.sequence.length]+'”'];feedback=`Bantuan ${level}/3: ${messages[level-1]}`;wrong=false;sound('hint');persist();render()};
const kluModeBeforeC3=kluMode;kluMode=function(s=state.scene,done=state.solved[s]){if(activeCase!=='C003')return kluModeBeforeC3(s,done);if(file)return'neutral';if(state.status==='completed'||s>=11)return'celebrate';if(wrong)return'thinking';if(feedback.startsWith('Bantuan'))return'hint';if(done||feedback.startsWith('✓'))return'excited';return'neutral'};
const renderBeforeC3=render;render=function(){if(activeCase!=='C003'){renderBeforeC3();return}document.querySelector('#sound').textContent=muted?'♪ Bunyi: Mati':'♪ Bunyi: Hidup';if(home){app.innerHTML=homeView();return}renderCase3()};
app.addEventListener('click',e=>{if(activeCase!=='C003')return;const b=e.target.closest('button');if(!b||b.disabled||b.dataset.case)return;e.stopImmediatePropagation?.();sound('ui-click');handleCase3Click(b)},true);
if(activeCase!=='C004')render();

